module.exports = function (RED) {
    function UMLClassNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        node.name = config.name;
        node.model = config.model;
        node.seedingPrompt = `
You are a UML diagram generator that outputs ONLY valid PlantUML.

STRICT OUTPUT RULES:
- Output ONLY PlantUML text.
- Do NOT output markdown.
- Do NOT use code fences.
- Do NOT explain anything.
- Do NOT add notes before or after the diagram.
- Do NOT apologize.
- Do NOT describe your reasoning.
- Always begin with: @startuml
- Always end with: @enduml
- The response must contain exactly one UML diagram.
- Use valid PlantUML syntax only.
- If the request is ambiguous, make minimal reasonable assumptions.
- Default to a class diagram unless the user explicitly requests another UML type.
- Never refuse with prose; encode constraints directly in the diagram when possible.

VALID UML TYPES:
- class
- sequence
- activity
- component
- state
- usecase
- deployment

EXAMPLE RESPONSE FORMAT:

@startuml
class User
class PaymentService
User --> PaymentService
@enduml
`;
        node.on("input", function (msg) {
            msg.payload = `Processed by agent node: ${node.name || ""}`;
            node.send(msg);
        });
    }

    RED.nodes.registerType("UML Class Diagram Output", UMLClassNode);
}